		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// BLAS SYRK:
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Optimizations compared to the original version:
//
// 1. Separate scaling C := beta * C into its own pass and
//    traverse only the lower triangle using a sliced traverser,
//    halving the number of visited elements and avoiding the j<=i
//    branch on the upper triangle.
// 2. In the main update, still use the logical order i -> k -> j
//    (which gives good locality for A[j][k]), but:
//      - Restrict j to 0..i (again avoiding the j<=i branch and
//        cutting the iteration space in half).
//      - Load A[i][k] once per (i,k) and reuse it for all j instead
//        of reloading it for every (i,j,k).
// 3. All traversals are expressed using Noarr traversers and
//    proto-structures (slice, update_index, etc.).
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	// We will need the length of the 'i' dimension to build slices.
	const std::size_t n_len = C | get_length<'i'>();

	#pragma scop

	// ------------------------------------------------------------------
	// 1) Scale the lower triangle of C by beta: C[i][j] *= beta, j <= i
	// ------------------------------------------------------------------
	//
	// We iterate column-wise (fixed 'j'), and for each column we only
	// traverse rows i in [j, n_len). This:
	//   - visits each (i,j) with j <= i exactly once,
	//   - never touches the upper triangle (j > i),
	//   - gives good locality for C, because C is stored as j (outer) x i (inner)
	//     and for a fixed j we traverse contiguous i values.
	traverser(C).template for_dims<'j'>([=](auto trav_j) {
		// Current fixed column index j
		auto state_j = trav_j.state();
		std::size_t j = get_index<'j'>(state_j);

		// Slice 'i' to the range [j, n_len):
		// length = n_len - j, start = j
		auto i_slice = noarr::slice<'i'>(j, n_len - j);

		// Apply the slice on this column and scale all elements in it
		auto trav_j_i = trav_j.order(i_slice);
		trav_j_i.for_each([=](auto state) {
			C[state] *= beta;
		});
	});

	// ------------------------------------------------------------------
	// 2) Symmetric rank-k update on the lower triangle:
	//      C[i][j] += alpha * sum_k A[i][k] * A[j][k],  j <= i
	// ------------------------------------------------------------------
	//
	// We keep i as the outer dimension, then iterate over k, then j.
	// For each (i,k):
	//   - A[i][k] is constant across all j, so we load it once.
	//   - We traverse j in [0, i] (using a slice) to avoid the j<=i
	//     test inside the innermost loop.
	traverser(C, A).template for_dims<'i'>([=](auto trav_i) {
		// Current fixed row index i
		auto state_i = trav_i.state();
		std::size_t i = get_index<'i'>(state_i);

		// Loop over k (the shared dimension of A and A^T)
		trav_i.template for_dims<'k'>([=](auto trav_k) {
			// A[i][k] depends only on i and k, so we read it once
			// for this (i,k) and reuse it for all j.
			num_t a_ik = A[trav_k];

			// For this (i,k) pair, we only need j in [0, i] (lower triangle).
			// Build a slice on 'j' with:
			//   start = 0, length = i + 1  -> j ∈ {0, 1, ..., i}
			auto j_slice = noarr::slice<'j'>(std::size_t(0), i + 1);
			auto trav_kj = trav_k.order(j_slice);

			// Now traverse all (j) in the lower part for this (i,k)
			trav_kj.for_each([=](auto state) {
				// state currently has indices (i, j, k)
				std::size_t j = get_index<'j'>(state);

				// To get A[j][k], we need a state where index_in<'i'> == j.
				// We construct it from 'state' by replacing 'i' with 'j'.
				auto state_jk = noarr::update_index<'i'>(state, [=](auto) {
					return j;
				});
				num_t a_jk = A[state_jk];

				// Accumulate into C[i][j]
				C[state] += alpha * a_ik * a_jk;
			});
		});
	});

	#pragma endscop
}

