		auto [i, j] = get_indices<'i', 'j'>(state);
		auto m_len = A | get_length<'k'>(); // use A's second dimension length (M)
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// Optimized layout-aware implementation:
//
// - C logical:  N x N (i x j), lower triangle (j <= i) updated
//   physical:  j (outer) x i (inner)  => columns of C are contiguous in memory
//
// - A logical: N x M (i x k)
//   physical:  k (outer) x i (inner)  => columns of A (fixed k) are contiguous
//
// We exploit this by:
//
// 1) Scaling the lower triangle of C by beta column-by-column (j-major):
//    each column j processed for rows i in [j, N), which are contiguous.
//
// 2) Performing the rank-k update in the order k -> j -> i, but still
//    updating C column-by-column and walking A column-by-column:
//      for each k:
//        for each column j:
//          load A[j][k] once
//          for i in [j, N):
//            C[i][j] += alpha * A[i][k] * A[j][k]
//
//    The innermost loop runs along i, which is the fastest-varying
//    dimension in both C (for fixed j) and A (for fixed k), maximizing
//    cache locality and enabling vectorization, while avoiding redundant
//    loads of A[j][k] and expensive state updates.
//
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// Phase 1: C := beta * C   (only for the lower triangle j <= i)
	// ------------------------------------------------------------------
	//
	// Traverse C column-by-column (j-major). For each fixed column j,
	// we only touch rows i >= j; those elements form one contiguous
	// segment in memory because 'i' is the inner dimension.
	//
	traverser(C).template for_dims<'j'>([&](auto trav_j) {
		// trav_j has 'j' fixed, 'i' remaining
		auto state_j = trav_j.state();
		std::size_t j = get_index<'j'>(state_j);

		// Restrict to i in [j, N) using a shift; the traverser returned
		// by order(...) yields states whose 'i' index is already the
		// global (unshifted) index, see shift() docs.
		auto trav_lower_col = trav_j.order(noarr::shift<'i'>(j));

		trav_lower_col.for_each([&](auto state) {
			// Here j is fixed, i >= j
			C[state] *= beta;
		});
	});

	// ------------------------------------------------------------------
	// Phase 2: C := C + alpha * A * A^T   (lower triangle only)
	// ------------------------------------------------------------------
	//
	// We traverse the combined (C, A) structure in the order:
	//   outer:  k  (columns of A)
	//   middle: j  (columns of C / rows of A)
	//   inner:  i  (rows of C / rows of A)
	//
	// For each (k, j):
	//   - load A[j][k] once (Ajk),
	//   - then for all i >= j:
	//       C[i][j] += alpha * A[i][k] * Ajk
	//
	// This matches the physical layouts:
	//   - for fixed j, C[i][j] with i increasing is contiguous,
	//   - for fixed k, A[i][k] with i increasing is contiguous.
	//
	auto trav = traverser(C, A)
		// re-order dimensions so that we end up with k -> j -> i nesting
		.order(noarr::hoist<'j'>() ^ noarr::hoist<'k'>());

	trav.template for_dims<'k'>([&](auto trav_k) {
		// trav_k has 'k' fixed, 'j' and 'i' remaining
		auto state_k = trav_k.state();
		std::size_t k = get_index<'k'>(state_k);

		// Iterate over columns j (still with this k fixed)
		trav_k.template for_dims<'j'>([&](auto trav_jk) {
			// trav_jk has 'k' and 'j' fixed, 'i' remaining
			auto state_jk = trav_jk.state();
			std::size_t j = get_index<'j'>(state_jk);

			// Load A[j][k] once for this (j, k) pair.
			// A is logically i x k, so we provide a state with i=j, k=k.
			auto state_Ajk = noarr::idx<'i', 'k'>(j, k);
			num_t a_jk = A[state_Ajk];

			// Restrict to i in [j, N) to honor j <= i (lower triangle).
			auto trav_ijk = trav_jk.order(noarr::shift<'i'>(j));

			trav_ijk.for_each([&](auto state) {
				// state has i >= j, and fixed j, k.
				// A[i][k] uses i and k from state; j is ignored by A.
				num_t a_ik = A[state];

				// C[i][j] += alpha * A[i][k] * A[j][k]
				C[state] += alpha * a_ik * a_jk;
			});
		});
	});

	#pragma endscop
}

