// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "syrk.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: i x j  (logical), layout proto
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k  (logical), layout proto
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A) {
	// C: i x j, length(i) = N, length(j) = N
	// A: i x k, length(i) = N, length(k) = M
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Hoist lengths and their reciprocals out of the element loops to
	// avoid recomputing them (and avoid a division per element).
	const std::size_t n_len = A | get_length<'i'>(); // N
	const std::size_t m_len = A | get_length<'k'>(); // M

	const num_t inv_n = num_t(1) / num_t(n_len);
	const num_t inv_m = num_t(1) / num_t(m_len);

	// A[i][k] = ( (i * k + 1) % n ) / n;
	noarr::traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		const num_t val = num_t((i * k + 1) % n_len) * inv_n;
		A[state] = val;
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	noarr::traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		const num_t val = num_t((i * j + 2) % m_len) * inv_m;
		C[state] = val;
	});
}

// computation kernel
// BLAS SYRK (lower triangle):
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// The implementation below keeps the original semantics but improves
// locality and reduces redundant work:
//  - scale C's lower triangle by beta using a triangular traversal
//  - then for each (i, k) load A[i][k] once and reuse it across all j
//  - access A[j][k] via explicit index states to avoid rebuilding
//    more complex states on every inner iteration
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// 1) Scale the lower triangular part of C by beta:
	//    for i in 0..N-1
	//      for j in 0..i
	//        C[i][j] *= beta;
	// ------------------------------------------------------------------
	noarr::traverser(C).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; 'j' varies
		auto state_i = trav_i.state();
		const std::size_t i = noarr::get_index<'i'>(state_i);

		// Restrict traversal to j in [0, i] using slice; this avoids
		// a branch on (j <= i) inside the inner loop and keeps the
		// access pattern contiguous in 'j'.
		auto lower_row_trav =
			trav_i.order(noarr::slice<'j'>(std::size_t(0), i + std::size_t(1)));

		lower_row_trav.for_each([&](auto state_ij) {
			// state_ij has both 'i' and 'j'
			C[state_ij] *= beta;
		});
	});

	// ------------------------------------------------------------------
	// 2) Rank-k update of the lower triangle:
	//
	//    for i in 0..N-1
	//      for k in 0..M-1
	//        t = alpha * A[i][k];
	//        for j in 0..i
	//          C[i][j] += t * A[j][k];
	//
	// This matches the original computation:
	//   C[i][j] += alpha * A[i][k] * A[j][k]  (for all k, j <= i)
	// but loads A[i][k] only once per (i,k) and avoids rebuilding
	// states via update_index for A[j][k].
	// ------------------------------------------------------------------
	noarr::traverser(C, A).template for_dims<'i'>([&](auto trav_i) {
		// Fix row index i once per outer iteration
		auto state_i = trav_i.state();
		const std::size_t i = noarr::get_index<'i'>(state_i);

		// Iterate all k for this i
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			auto state_ik = trav_ik.state();
			const std::size_t k = noarr::get_index<'k'>(state_ik);

			// A[i][k]: load once per (i,k) and pre-multiply by alpha.
			// We build a minimal state for A that only contains the
			// dimensions that A actually uses ('i', 'k').
			const num_t a_ik        = A[noarr::idx<'i', 'k'>(i, k)];
			const num_t alpha_a_ik  = alpha * a_ik;

			// Restrict j to 0..i and traverse the lower part only.
			auto lower_row_trav =
				trav_ik.order(noarr::slice<'j'>(std::size_t(0), i + std::size_t(1)));

			lower_row_trav.for_each([&](auto state_ijk) {
				// state_ijk has ('i', 'j', 'k').
				const std::size_t j = noarr::get_index<'j'>(state_ijk);

				// C[i][j] += alpha * A[i][k] * A[j][k]
				// A[j][k] uses i-dimension index j, so we build a small
				// state containing exactly ('i' = j, 'k' = k).
				const num_t a_jk = A[noarr::idx<'i', 'k'>(j, k)];

				C[state_ijk] += alpha_a_ik * a_jk;
			});
		});
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t alpha;
	num_t beta;

	// set lengths for each structure
	auto set_lengths_C = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);
	auto set_lengths_A = noarr::set_length<'i'>(n) ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths_C);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths_A);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syrk(alpha, beta, C.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to print C in i-major order
