// initialization function
// ---------------------------------------------------------------------------
void init_array(num_t &alpha, num_t &beta, auto C, auto A) {
	// C: i x j, length(i) = N, length(j) = N
	// A: i x k, length(i) = N, length(k) = M
	using namespace noarr;

	alpha = static_cast<num_t>(1.5);
	beta  = static_cast<num_t>(1.2);

	// Pre-compute lengths once; they are invariant inside the traversals.
	const std::size_t n_len = A | get_length<'i'>(); // N
	const std::size_t m_len = A | get_length<'k'>(); // M

	// A[i][k] = ( (i * k + 1) % n ) / n;
	// Traversal order is i (outer) x k (inner), matching A's row-major layout.
	traverser(A).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		const std::size_t val = (i * k + 1) % n_len;
		A[state] = static_cast<num_t>(val) / static_cast<num_t>(n_len);
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	// Use A's second-dimension length (M), as in the original code.
	// Traversal order is i (outer) x j (inner), matching C's layout.
	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		const std::size_t val = (i * j + 2) % m_len;
		C[state] = static_cast<num_t>(val) / static_cast<num_t>(m_len);
	});
}

// ---------------------------------------------------------------------------
// computation kernel
// ---------------------------------------------------------------------------
//
// BLAS SYRK:
//
//   C := alpha * A * A^T + beta * C
//
// A is N x M (i x k)
// C is N x N (i x j), only the lower triangle (j <= i) is updated.
//
// Data layouts:
//
//   A: dims 'i' (outer), 'k' (inner)  ->  rows are contiguous in k
//   C: dims 'i' (outer), 'j' (inner)  ->  rows are contiguous in j
//
// We iterate as:
//
//   for i
//     for j <= i
//       c_ij = beta * C(i,j)
//       for k
//         c_ij += alpha * A(i,k) * A(j,k)
//
// The traversal order (i outer, j middle, k inner) keeps:
//   - C accesses contiguous along j for fixed i,
//   - A accesses contiguous along k for both rows i and j,
//   while keeping the code fully expressed via Noarr traversers.
//
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop
	// Joint traverser over C and A; dimensions are the union {i, j, k}.
	traverser(C, A).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, remaining free dimensions: 'j', 'k'.
		auto state_i = trav_i.state();
		const auto i = get_index<'i'>(state_i);

		// For this row i, walk all columns j.
		// We explicitly skip j > i to keep only the lower triangle.
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			auto state_ij = trav_ij.state(); // contains i and j
			const auto j = get_index<'j'>(state_ij);

			// Only update the lower triangular part (j <= i).
			if (j > i)
				return;

			// Load C(i,j), apply beta scaling once, keep in a register.
			num_t c_ij = C[state_ij] * beta;

			// For this fixed (i,j), trav_ij still has 'k' free.
			// for_each will iterate k in the layout-friendly order.
			trav_ij.for_each([&](auto state_ijk) {
				// state_ijk carries i, j, k.
				const auto k = get_index<'k'>(state_ijk);

				// A(i,k): uses indices 'i' and 'k' from the state.
				const num_t a_ik = A[state_ijk];

				// A(j,k): build a minimal state with 'i' replaced by j.
				// Using idx<'i','k'> keeps this cheap and explicit.
				const auto state_jk = noarr::idx<'i', 'k'>(j, k);
				const num_t a_jk = A[state_jk];

				// Accumulate contribution for this (i,j).
				c_ij += alpha * a_ik * a_jk;
			});

			// Store the final value back into C.
			C[state_ij] = c_ij;
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t alpha;
	num_t beta;

	// set lengths for each structure
	auto set_lengths_C = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);
	auto set_lengths_A = noarr::set_length<'i'>(n) ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths_C);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths_A);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syrk(alpha, beta, C.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to print C in i-major order
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
