// computation kernel
// C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Optimizations compared to the original version:
//  - Scale C by beta in a separate pass using a slice over j to avoid a branch on (j <= i).
//  - Reorder main computation loops to iterate k outermost -> better reuse of A(:,k).
//  - Hoist A[i][k] out of the inner j-loop and pre-multiply by alpha.
//  - Use noarr::slice<'j'>(0, i+1) to iterate only j <= i, eliminating the branch inside the hot loop.
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------------------------------
	// 1) Scale the lower triangular part of C by beta: C[i][j] *= beta
	//    for all 0 <= j <= i < N.
	// ---------------------------------------------------------------------
	traverser(C).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, and still contains the 'j' dimension.
		auto state_i = trav_i.state();
		std::size_t i = get_index<'i'>(state_i);

		// Restrict the traversal to j in [0, i].
		// slice<Dim>(start, length) keeps indices start .. start+length-1.
		auto lower_row = trav_i.order(noarr::slice<'j'>(std::size_t(0), i + 1));

		lower_row.for_each([&](auto state) {
			// state has (i, j); only j <= i are visited due to the slice above.
			C[state] *= beta;
		});
	});

	// ---------------------------------------------------------------------
	// 2) C[i][j] += alpha * sum_k A[i][k] * A[j][k]  for all j <= i.
	//
	//    We iterate k outermost for better reuse of A(:,k), then i, then j.
	//    For each (i,k) pair we:
	//      - load A[i][k] once
	//      - precompute alpha * A[i][k]
	//      - traverse j in [0, i] and accumulate into C[i][j]
	// ---------------------------------------------------------------------
	traverser(A, C).template for_dims<'k'>([&](auto trav_k) {
		// trav_k has 'k' fixed, traverses over 'i' and 'j'.
		auto state_k = trav_k.state();
		std::size_t k = get_index<'k'>(state_k);

		// For each row index i
		trav_k.template for_dims<'i'>([&](auto trav_ki) {
			// trav_ki has both 'k' and 'i' fixed, traverses over 'j'.
			auto state_ki = trav_ki.state();
			std::size_t i = get_index<'i'>(state_ki);

			// Load A[i][k] once for this (i, k), j is irrelevant for A.
			num_t a_ik = A[state_ki];
			num_t alpha_a_ik = alpha * a_ik;

			// Restrict j to the lower triangle: 0 <= j <= i.
			auto lower_row = trav_ki.order(noarr::slice<'j'>(std::size_t(0), i + 1));

			lower_row.for_each([&](auto state) {
				// state has (i, j, k) with j in [0, i]
				std::size_t j = get_index<'j'>(state);

				// Build a state for A[j][k]; A only cares about dimensions 'i' and 'k'.
				auto state_jk = noarr::idx<'i', 'k'>(j, k);
				num_t a_jk = A[state_jk];

				C[state] += alpha_a_ik * a_jk;
			});
		});
	});

	#pragma endscop
}

